import UserPage from 'flarum/forum/components/UserPage';
import LinkButton from 'flarum/common/components/LinkButton';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { certificateUrl, userCourses } from '../../common/api';
import CourseCard from '../components/CourseCard';
import { failed, t } from '../components/util';

/** Profile → Courses: what the member is taking and has completed, unless they keep it to themselves. */
export default class UserCoursesPage extends UserPage {
  courses = null;
  hidden = false;
  shownFor = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    if (this.shownFor === user.id()) return;
    this.shownFor = user.id();
    this.courses = null;
    userCourses(user.id()).then(({
      data,
      meta
    }) => {
      this.courses = data;
      this.hidden = meta.hidden;
      m.redraw();
    }, failed);
  }
  content() {
    if (!this.courses) return m(LoadingIndicator, {
      display: "block"
    });
    if (this.hidden) return m("p", {
      className: "SyllabusEmpty"
    }, t('profile.hidden'));
    if (!this.courses.length) return m("p", {
      className: "SyllabusEmpty"
    }, t('profile.empty'));
    const doing = this.courses.filter(c => !c.me?.completedAt);
    const done = this.courses.filter(c => c.me?.completedAt);
    return m("div", {
      className: "SyllabusUserPage"
    }, doing.length ? m("h3", {
      className: "SyllabusHeading"
    }, t('profile.in_progress')) : null, m("div", {
      className: "SyllabusGrid"
    }, doing.map(course => m(CourseCard, {
      key: course.id,
      course: course
    }))), done.length ? m("h3", {
      className: "SyllabusHeading"
    }, t('profile.completed')) : null, m("div", {
      className: "SyllabusGrid"
    }, done.map(course => m("div", {
      className: "SyllabusGrid-item",
      key: course.id
    }, m(CourseCard, {
      course: course
    }), course.certificateCode ? m(LinkButton, {
      className: "Button Button--link",
      icon: "fas fa-award",
      href: certificateUrl(course.certificateCode)
    }, t('course.view_certificate')) : null))));
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/pages/UserCoursesPage', UserCoursesPage);