import Component from 'flarum/common/Component';
import { t } from './util';

/** A labelled progress bar: "3 of 8 lessons · 37%". */
export default class ProgressBar extends Component {
  view() {
    const {
      percent,
      done,
      total,
      compact
    } = this.attrs;
    const label = t('progress.label', {
      percent
    });
    return m("div", {
      className: 'SyllabusProgress' + (compact ? ' SyllabusProgress--compact' : '')
    }, m("div", {
      className: "SyllabusProgress-bar",
      role: "progressbar",
      "aria-valuemin": "0",
      "aria-valuemax": "100",
      "aria-valuenow": percent,
      "aria-label": label
    }, m("span", {
      style: {
        width: percent + '%'
      }
    })), !compact ? m("div", {
      className: "SyllabusProgress-text"
    }, total !== undefined ? t('progress.lessons', {
      done: done || 0,
      total
    }) : null, m("span", {
      className: "SyllabusProgress-percent"
    }, label)) : null);
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/components/ProgressBar', ProgressBar);